import{_ as a,o as s,c as t,au as i}from"./chunks/framework.DGGy0Y3v.js";const u=JSON.parse('{"title":"Browser and Package Checks","description":"","frontmatter":{},"headers":[],"relativePath":"testing/browser.md","filePath":"testing/browser.md","lastUpdated":1793549075000}'),o={name:"testing/browser.md"};function n(r,e,l,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="browser-and-package-checks" tabindex="-1">Browser and Package Checks <a class="header-anchor" href="#browser-and-package-checks" aria-label="Permalink to &quot;Browser and Package Checks&quot;">​</a></h1><p>Use Node 22 and the existing installed dependencies. No additional test package or browser download is needed. Set <code>CHROME_BIN</code> to a Chrome/Chromium executable if it is not in a supported system location. The runner launches an isolated temporary profile and deletes it afterward. It never connects to your normal browser.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:visual</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:package</span></span></code></pre></div><h2 id="coverage" tabindex="-1">Coverage <a class="header-anchor" href="#coverage" aria-label="Permalink to &quot;Coverage&quot;">​</a></h2><p><code>test:browser</code> starts Vite on localhost and sends native keyboard, mouse and touch input through Chrome&#39;s debugging protocol. Assertions cover modal focus isolation/restoration, hidden/disabled targets, nested dialogs, drawer Escape, autocomplete input focus, select boundaries, submenu navigation, controlled values, radio groups, ripple release, fields, picker gestures and removal/unmount. Unit tests cover cancellation, registration and listener/timer cleanup where browser assertions alone cannot prove it.</p><p><code>test:visual</code> compares deterministic geometry and computed-style samples against <code>tests/browser/visual-baseline.json</code>. It saves full-page PNGs for light/dark, RTL/narrow, enlarged field/button text and disabled/loading states in <code>test-results/browser/</code>. CI uploads these files for visual review. <strong>This is a geometry/style regression check plus screenshot review, not pixel-difference testing.</strong> Borders, shadows, glyph rendering and unsampled positions require human review. System fonts deliberately avoid network font dependencies. The font prerequisites below must be checked in the consuming application too.</p><p>After reviewing a deliberate change, update measured baselines with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:visual</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><p>Review both JSON changes and PNG artifacts. Chrome reports its version in the log. Browser rendering can change when CI&#39;s preinstalled Chrome updates; inspect baseline failures instead of automatically accepting them. Tests do not claim Firefox/WebKit, screen-reader or physical-device coverage. Fixture text enlargement is a layout stress check, not a substitute for OS/browser 200% zoom testing.</p><p><code>test:package</code> builds and packs the actual artifact into a temporary directory, checks its public UMD/ES/CSS paths and Vue peer metadata, builds a consumer using only package imports, and renders it in Chrome to assert its CSS and components. It reuses already installed Vue/dayjs through symlinks; it never runs <code>npm install</code> or publishes. Missing Vue is declared as a required peer, and the compatibility range excludes Vue 3.4 because components use Vue 3.5 <code>useId</code>. It checks metadata and a supported installed runtime, not npm&#39;s resolver in every npm version.</p><h2 id="storybook-prerequisites" tabindex="-1">Storybook prerequisites <a class="header-anchor" href="#storybook-prerequisites" aria-label="Permalink to &quot;Storybook prerequisites&quot;">​</a></h2><p>Package consumers must import <code>vue-material-3/style.css</code> once. Roboto and Material Symbols Outlined are external font prerequisites: load them in the application, or supply your own typography/icon content. Storybook&#39;s preview config supplies fonts for the examples; they are not bundled into the package.</p><p>Existing field/select/autocomplete stories feed emitted model values back into a parent ref, and watch incoming controls so Storybook updates also reach the parent. Use Controls for supported disabled, readonly and error states; use a <code>.dark</code> container for dark tokens. <code>modelValue</code> takes precedence over a legacy <code>value</code>; select&#39;s <code>value</code> is an initial default, while text-field legacy <code>value</code> stays reactive only when <code>modelValue</code> is absent. See each <a href="/vue-material-3/components/">component reference</a> for key props, events, and slots.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><p>These checks do not establish full visual or accessibility conformance. Geometry/style assertions and screenshots complement manual review; they do not compare pixels. Review historical reports against their own source receipts rather than treating their test counts as current.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/vue-material-3/guide/installation">Installation</a></li><li><a href="/vue-material-3/components/">Components</a></li><li><a href="https://mylmz10.github.io/vue-material-3/storybook/" target="_blank" rel="noreferrer">Storybook</a></li></ul>`,18)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
